/* Originally generated by Payload. Customised: applies the Lets Tour admin structure
   (see ../../_admin/applyAdminStructure.ts) before rendering. */
import type { Metadata } from 'next'

import config from '@payload-config'
import { RootPage, generatePageMetadata } from '@payloadcms/next/views'
import { importMap } from '../importMap'
import { applyAdminStructure } from '../../_admin/applyAdminStructure'

type Args = {
  params: Promise<{
    segments: string[]
  }>
  searchParams: Promise<{
    [key: string]: string | string[]
  }>
}

// The admin (including the login page) must never be indexed, cached or previewed
// by any search engine or bot. Pairs with the X-Robots-Tag header in next.config.js.
const NO_INDEX: Metadata['robots'] = {
  index: false,
  follow: false,
  nocache: true,
  noarchive: true,
  nosnippet: true,
  noimageindex: true,
  googleBot: { index: false, follow: false, noimageindex: true, nosnippet: true },
}

export const generateMetadata = async ({ params, searchParams }: Args): Promise<Metadata> => ({
  ...(await generatePageMetadata({ config, params, searchParams })),
  robots: NO_INDEX,
})

const Page = async ({ params, searchParams }: Args) => {
  await applyAdminStructure(config)
  return RootPage({ config, params, searchParams, importMap })
}

export default Page
